// Builds `usage-lib.js` for the sync agent from the server's own usage readers
// (lib/claude-usage.js, lib/codex-usage.js, lib/antigravity-usage.js), so the
// agent and the local tracker read limits with the SAME code. The installer
// writes the result next to the agent's index.js. The readers only require
// Node built-ins, which is what makes this wrapping possible — a test pins it.

const fs = require('fs');
const path = require('path');

const MODULES = [
  ['claude', 'claude-usage.js'],
  ['codex', 'codex-usage.js'],
  ['antigravity', 'antigravity-usage.js']
];

function buildUsageBundle(libDir = __dirname) {
  const parts = [
    "'use strict';",
    '// GENERATED by lib/agent-usage-bundle.js from the token tracker\'s lib/ — do not edit.',
    'const _mods = {};',
    'function _def(name, fn) { const module = { exports: {} }; fn(module, module.exports, require); _mods[name] = module.exports; }'
  ];
  for (const [name, file] of MODULES) {
    const src = fs.readFileSync(path.join(libDir, file), 'utf8');
    parts.push(`_def(${JSON.stringify(name)}, function (module, exports, require) {\n${src}\n});`);
  }
  parts.push('module.exports = _mods;');
  return parts.join('\n') + '\n';
}

module.exports = { buildUsageBundle, MODULES };
